package com.example.bikerental; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="waitlist_entries") public class WaitlistEntry { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String username; @ManyToOne(optional=false) private Bike bike; private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) private boolean notified=false; public WaitlistEntry(){} public WaitlistEntry(String u,Bike b){username=u;bike=b;} public Long getId(){return id;} public String getUsername(){return username;} public Bike getBike(){return bike;} public LocalDateTime getCreatedAt(){return createdAt;} public boolean isNotified(){return notified;} public void setNotified(boolean v){notified=v;} }